pub fn write_deterministic_deflate_zip(root: &Path, output: &Path, manifest: &BundleManifest) -> Result<(), String> {
    if manifest.is_empty() { return Err("cannot write an empty bundle manifest".to_owned()); }
    if manifest.len() > usize::from(u16::MAX) { return Err(format!("too many bundle entries: {}", manifest.len())); }
    if output.starts_with(root) { return Err("zip output must be outside bundle root".to_owned()); }
    if let Some(parent) = output.parent() { fs::create_dir_all(parent).map_err(|error| error.to_string())?; }
    let stage = stage_path(output);
    let result = (|| -> Result<(), String> {
        let file = OpenOptions::new().write(true).create_new(true).open(&stage).map_err(|error| format!("create exclusive stage {}: {error}", stage.display()))?;
        let mut writer = ZipWriter::new(file);
        let timestamp = DateTime::default();
        for name in manifest.entries() {
            let path = root.join(name);
            let metadata = fs::symlink_metadata(&path).map_err(|error| format!("stat {}: {error}", path.display()))?;
            if metadata.file_type().is_symlink() || !metadata.is_file() { return Err(format!("manifest entry is not a regular file: {}", path.display())); }
            #[cfg(unix)]
            let permissions = metadata.permissions().mode() & 0o7777;
            #[cfg(not(unix))]
            let permissions = (external_attributes(&metadata, &path) >> 16) & 0o7777;
            let options = FileOptions::default()
                .compression_method(CompressionMethod::Deflated)
                .compression_level(Some(9))
                .last_modified_time(timestamp)
                .unix_permissions(permissions);
            writer.start_file(name, options).map_err(|error| format!("start deflate entry {name}: {error}"))?;
            let mut source = File::open(&path).map_err(|error| format!("open {}: {error}", path.display()))?;
            std::io::copy(&mut source, &mut writer).map_err(|error| format!("deflate {}: {error}", path.display()))?;
        }
        let file = writer.finish().map_err(|error| format!("finish deflate zip: {error}"))?;
        file.sync_all().map_err(|error| error.to_string())?;
        fs::rename(&stage, output).map_err(|error| error.to_string())?;
        Ok(())
    })();
    if result.is_err() { let _ = fs::remove_file(&stage); }
    result
}


